import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fetchAll } from '../fetch.js';
const slow = (id) => new Promise((r) => setTimeout(() => r(id * 10), (5 - id) * 15));
test('order kept', async () => assert.deepEqual(await fetchAll([1, 2, 3, 4], slow), [10, 20, 30, 40]));
test('parallel', async () => {
  let running = 0, peak = 0;
  await fetchAll([1, 2, 3], async (id) => { running++; peak = Math.max(peak, running); await new Promise((r) => setTimeout(r, 20)); running--; return id; });
  assert.equal(peak, 3);
});
test('rejects', async () => assert.rejects(fetchAll([1, 2], async (id) => { if (id === 2) throw new Error('boom'); return id; }), /boom/));

